from solution import topological_sort

def test_linear_dependency():
    # A -> B -> C
    graph = {'A': ['B'], 'B': ['C'], 'C': []}
    result = topological_sort(graph)
    # The order must be [C, B, A] because C is the dependency of B, B is dependency of A
    assert result == ['C', 'B', 'A']

def test_multiple_dependencies():
    # A depends on B and C; B depends on D; C depends on D
    graph = {'A': ['B', 'C'], 'B': ['D'], 'C': ['D'], 'D': []}
    result = topological_sort(graph)
    # D must come first, then B and C (in any order), then A
    assert result.index('D') < result.index('B')
    assert result.index('D') < result.index('C')
    assert result.index('B') < result.index('A')
    assert result.index('C') < result.index('A')
    assert len(result) == 4

def test_detect_simple_cycle():
    # A -> B -> A
    graph = {'A': ['B'], 'B': ['A']}
    try:
        topological_sort(graph)
    except ValueError as e:
        assert str(e) == 'cycle detected'
    else:
        assert False, "Should have raised ValueError for cycle"

def test_detect_self_loop():
    # A -> A
    graph = {'A': ['A']}
    try:
        topological_sort(graph)
    except ValueError as e:
        assert str(e) == 'cycle detected'
    else:
        assert False, "Should have raised ValueError for self-loop"

def test_detect_complex_cycle():
    # A -> B -> C -> D -> B (Cycle is B-C-D)
    graph = {'A': ['B'], 'B': ['C'], 'C': ['D'], 'D': ['B']}
    try:
        topological_sort(graph)
    except ValueError as e:
        assert str(e) == 'cycle detected'
    else:
        assert False, "Should have raised ValueError for complex cycle"

def test_empty_graph():
    graph = {}
    result = topological_sort(graph)
    assert result == []

def test_disconnected_components():
    # A -> B and C -> D (Two separate islands)
    graph = {'A': ['B'], 'B': [], 'C': ['D'], 'D': []}
    result = topological_sort(graph)
    assert len(result) == 4
    assert result.index('B') < result.index('A')
    assert result.index('D') < result.index('C')

