```python
def topological_sort(graph):
    visited = set()
    path = set()
    order = []

    def visit(node):
        if node in path:
            raise ValueError('cycle detected')
        if node in visited:
            return

        path.add(node)
        visited.add(node)

        for dependency in graph.get(node, []):
            visit(dependency)

        path.remove(node)
        order.append(node)

    # We must ensure all nodes in the graph are processed, 
    # including those that might only appear as dependencies.
    all_nodes = set(graph.keys())
    for neighbors in graph.values():
        for n in neighbors:
            all_nodes.add(n)

    for node in all_nodes:
        if node not in visited:
            visit(node)

    return order
```

