def topological_sort(graph):
    visited = set()
    path = set()
    order = []

    def visit(node):
        if node in path:
            raise ValueError('cycle detected')
        if node in visited:
            return

        path.add(node)
        visited.add(node)

        for dependency in graph.get(node, []):
            visit(dependency)

        path.remove(node)
        order.append(node)

    # We must ensure all nodes present in the graph (keys and values) are covered
    # and handle potential nodes that are only targets of edges.
    all_nodes = set(graph.keys())
    for neighbors in graph.values():
        for n in neighbors:
            all_nodes.add(n)

    for node in all_nodes:
        if node not in visited:
            visit(node)

    return order[::-1]
