from solution import clean_path

def test_basic_collapse():
    # Test simple repeated slashes
    assert clean_path("///usr///bin") == "/usr/bin"

def test_preserve_relative_path():
    # Test that relative paths (no leading slash) remain relative
    assert clean_path("home//user///docs") == "home/user/docs"

def test_preserve_absolute_path():
    # Test that absolute paths remain absolute
    assert clean_path("/a//b/c///d") == "/a/b/c/d"

def test_empty_string():
    # Test behavior with an empty string
    assert clean_path("") == ""

def test_single_slash():
    # Test that a single slash is not collapsed to nothing
    assert clean_path("/") == "/"

def test_trailing_slashes():
    # Test that trailing slashes are also collapsed
    assert clean_path("/usr/local///") == "/usr/local/"

def test_mixed_slashes():
    # Test complex patterns of repeated slashes
    assert clean_path("////var////log//syslog") == "/var/log/syslog"

